// EBX is not an argument: the body never reads it.
void DRAW_Overlay_SecondsLeftToGame() {
    int nClearCount;
    uint16_t wszText[256];
    int32_t nHighResTime = Fog::Src::LogManager::LOGMGR_GetHighResolutionTime();
    if (!(gnGameEndTime && gnGameEndTime > nHighResTime)) {
      return;
    }

    D2UnitStrc* pQuestMonster = UNIT::Player::UNITS_FindClientSideUnit(gnQuestMonsterUnitId, UNIT_MONSTER);
    if (!(!pQuestMonster || pQuestMonster->eAnimMode.ePlayerMode == Kick || gnGameEndTime - 0x46 <= nHighResTime)) {
      return;
    }

    int32_t nSecondsLeft = gnGameEndTime - nHighResTime;
    for (nClearCount = 0; nClearCount < 0x100; nClearCount++) {
      wszText[nClearCount] = L'\0';
    }

    uint16_t* pFormatStr = D2Lang::StrTable::strtable::GetLocaleString(0x13e9);
    D2Lang::Unicode::UNISYS::UNICODE_FormatWideString(0x100, wszText, pFormatStr, nSecondsLeft);
    int32_t nSavedFont = D2Win::Src::D2WinFont::SetAndReturnLastFont(0xd);
    int32_t nTextWidth = D2Win::Src::D2WinFont::DRAW_text0(wszText);
    D2Win::Src::D2WinFont::DRAW_text(wszText, ScreenSizeX / 2 - nTextWidth / 2, 0x177, 9, 1);
    D2Win::Src::D2WinFont::SetAndReturnLastFont(nSavedFont);
}

