static void __stdcall ROOM_FindSpawnPositionForMonster(D2RoomStrc * pRoom, int32_t nMonsterClassId, uint32_t * pSeed) {
    uint32_t nRandOffset;
    D2DrlgRoomCoordsStrc sRoomCoords;
    uint64_t nSeedModBranch;
    int64_t nSeedPow2Branch;
    int nY;
    D2Common::DUNGEON::Dungeon::DRLGROOM_GetRoomCoordinates(pRoom, &sRoomCoords);
    int nXStart = sRoomCoords.dwXStart;
    int nYStart = sRoomCoords.dwYStart;
    uint32_t nXRange = sRoomCoords.dwXSize - 1;
    uint32_t nYRange = sRoomCoords.dwYSize - 1;
    if (!(nMonsterClassId >= 0 && nMonsterClassId < sgptDataTable->nTxtMonStatsSize)) {
      return;
    }

    int nSpawnX = (int)sgptDataTable->pTxtMonStats[nMonsterClassId].MonStatsEx;
    D2MonStats2Txt* pMonStatsExTxt = nSpawnX >= 0 && nSpawnX < sgptDataTable->nTxtMonStatsExSize ? sgptDataTable->pTxtMonStatsEx + nSpawnX : nullptr;
    if (!pMonStatsExTxt) {
      return;
    }

    eD2CollisionUnitSize nMonsterSizeX = (eD2CollisionUnitSize)pMonStatsExTxt->SizeX;
    int nAttempts = 0;
    while (true) {
      eCollisionFlags eCollision;
      if ((int)nXRange <= 0) {
        nRandOffset = 0;
      } else if (nXRange & nXRange - 1) {
        nSeedModBranch = (uint64_t)*pSeed * 0x6ac690c5 + (uint64_t)pSeed[1];
        *(uint64_t*)pSeed = nSeedModBranch;
        nRandOffset = (uint32_t)((nSeedModBranch & 0xffffffff) % (uint64_t)nXRange);
      } else {
        nSeedPow2Branch = (uint64_t)*pSeed * 0x6ac690c5 + (uint64_t)pSeed[1];
        *(int64_t*)pSeed = nSeedPow2Branch;
        nRandOffset = nXRange - 1 & (uint32_t)nSeedPow2Branch;
      }

      nSpawnX = nRandOffset + nXStart;
      if ((int)nYRange <= 0) {
        nRandOffset = 0;
      } else if (nYRange & nYRange - 1) {
        nSeedModBranch = (uint64_t)*pSeed * 0x6ac690c5 + (uint64_t)pSeed[1];
        *(uint64_t*)pSeed = nSeedModBranch;
        nRandOffset = (uint32_t)((nSeedModBranch & 0xffffffff) % (uint64_t)nYRange);
      } else {
        nSeedPow2Branch = (uint64_t)*pSeed * 0x6ac690c5 + (uint64_t)pSeed[1];
        *(int64_t*)pSeed = nSeedPow2Branch;
        nRandOffset = nYRange - 1 & (uint32_t)nSeedPow2Branch;
      }

      nY = nRandOffset + nYStart;
      eCollision = D2Common::Collision::CheckCollision_BlockAll_Width(pRoom, nSpawnX, nY, nMonsterSizeX, 0x3f11);
      if (eCollision == COLLIDE_NONE) {
        break;
      }

      nAttempts++;
      if (nAttempts >= 10) {
        return;
      }
    }

    if (nAttempts >= 10) {
      return;
    }

    UNIT::CUnit::CreateMissileOrMonster(nMonsterClassId, nSpawnX, nY, UNIT_MONSTER, 0);
}

