// CLIENT-SIDE AI BEHAVIOR DISPATCHER:
// Similar to server-side 4-stage pipeline but simpler
// Finds closest tracked unit or player, sends network messages:
// - Wander (0x19 frame delay if no target)
// - Chase (distance-based behavior)
// - Attack (if in range)
// - Special cases: Corpse seekers, idle wanderers, basic chase
// Called from CUNIT_UpdateClientFramesAndAI
void __fastcall CLIENT_DispatchMonsterAiBehavior(D2UnitStrc * pUnit) {
    int32_t nClosestDist;
    nClosestDist = (int32_t)pUnit;
    int32_t* pnAiDelay;
    pnAiDelay = UNIT::Monster::GetMonsterAi(pUnit);
    if (!pnAiDelay) {
      return;
    }
    if (*pnAiDelay > 0) {
      (*pnAiDelay)--;
      return;
    }

    nClosestDist = 0x7fffffff;
    D2UnitStrc* pTarget;
    pTarget = CLIENT_FindClosestTrackedUnit(pUnit, &nClosestDist);
    if (!pTarget) {
      pTarget = UNIT::Player::GetPlayerUnit_UI();
      if (!pTarget) {
        pnAiDelay = UNIT::Monster::GetMonsterAi(pUnit);
        if (pnAiDelay) {
          *pnAiDelay = 0x19;
        }

        CLIENT_SendMonsterWanderMessage(pUnit);
        return;
      }
    }
    if (nClosestDist > 0x1e) {
      CLIENT_SetMonsterAiTimer(pUnit, nClosestDist - 0xf);
      goto send_wander;
    }

    BOOL bIsZooFlag;
    bIsZooFlag = DataTbls::MonsterTbls::TXT_MonStats_GetFlagsByBitOffset(pUnit->nClassId, zoo);
    if (bIsZooFlag) {
      MONSTER_ProcessPathCallback(pUnit, pTarget);
      return;
    }

    int iVar1;
    iVar1 = pUnit->nClassId;
    if (iVar1 <= 0x22c) {
      int32_t nDistCopy;
      nDistCopy = nClosestDist;
      if (iVar1 == 0x22c) {
        CLIENT_MonsterSeekCorpse(pUnit);
        return;
      }
      if (false) {
        send_wander:
        CLIENT_SendMonsterWanderMessage(pUnit);
        return;
      }

      switch (iVar1) {
        case 0x95:

        case 0x10c:
          MONSTER_FindAndChaseNearestEnemy(pUnit);
        return;
        default:
          goto send_wander;
        case 0x9f:
          CLIENT_MonsterAi_IdleWanderBehavior(pTarget, nDistCopy, pUnit);
        return;
        case 0x9d:

        case 0x9e:

        case 0x13f:
          CLIENT_MonsterIdleApproach(pUnit);
        return;
        case 0xe3:
          CLIENT_MonsterThinkBehavior(pUnit, pTarget);
        return;
        case 0x116:

        case 0x117:

        case 0x118:

        case 0x119:

        case 0x11a:
          goto done;
        case 0x97:

        case 0x10d:

        case 0x11b:

        case 0x153:
          CLIENT_MonsterAi_CorpseSeekerBehavior(nDistCopy, pTarget, pUnit);
        return;
        case 0x13e:
          CLIENT_MonsterAi_BasicChaseBehavior(nDistCopy, pTarget, pUnit);
        return;
      }
    }
    if (iVar1 != 0x23e) {
      goto send_wander;
    }

    CLIENT_SpawnWorldstoneChipDebris(pUnit);
    done:
    ;
}

